/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(get_vault_dashboard))
        .routes(routes!(list_vault_feed))
        .routes(routes!(list_vault_reminders))
        .routes(routes!(list_vault_tasks))
        .routes(routes!(get_vault_calendar_month))
        .routes(routes!(get_vault_calendar_day))
        .routes(routes!(get_vault_address_report))
        .routes(routes!(get_vault_city_address_report))
        .routes(routes!(get_vault_country_address_report))
        .routes(routes!(get_vault_mood_tracking_report))
        .routes(routes!(get_vault_important_date_report))
        .routes(routes!(list_vault_life_metrics, create_vault_life_metric))
        .routes(routes!(update_vault_life_metric, delete_vault_life_metric))
        .routes(routes!(increment_vault_life_metric))
        .routes(routes!(list_vault_files))
        .routes(routes!(delete_vault_file))
        .routes(routes!(get_vault_file_content))
        .routes(routes!(list_vault_companies, create_vault_company))
        .routes(routes!(search_vault))
}
